type CreateDomainResponseRecordsItem struct {
	// One sentence explaining a row that is not verified: found but awaiting the
	// provider, the value that is published instead, no record at the name, or
	// which parent DMARC policy covers the domain. Omitted when there is nothing
	// to add.
	Detail *string `json:"detail,omitempty"`
	// DMARC only: the _dmarc name whose policy covers this domain when it has no
	// record of its own (RFC 7489 organizational-domain fallback).
	InheritedFrom *string `json:"inherited_from,omitempty"`
	// What public DNS answers for this record right now: found, missing, mismatch
	// (a different value is published) or unknown (the lookup did not conclude).
	// Omitted when no live check ran (the create response). One of: "found",
	// "missing", "mismatch", "unknown".
	Live *string `json:"live,omitempty"`
	Name string  `json:"name"`
	// DMARC only, alongside inherited_from: the inherited policy's p= value. One
	// of: "none", "quarantine", "reject".
	Policy   *string  `json:"policy,omitempty"`
	Priority *float64 `json:"priority,omitempty"`
	// Which record this is: DKIM, SPF (the MAIL FROM MX and TXT rows), DMARC,
	// Tracking (the tracking subdomain's CNAME, present once a tracking subdomain
	// is set), Unsubscribe (the unsubscribe subdomain's CNAME, present once an
	// unsubscribe subdomain is set to a label other than the tracking one) or
	// Receiving (the MX inbound mail needs, present while receiving is enabled; it
	// reads verified only when it is among the domain's lowest-numbered MX
	// records). Only the DKIM and SPF rows gate sending.
	Record string `json:"record"`
	// not_started | pending | verified | failed. DKIM and SPF rows combine public
	// DNS with the provider's verification: found in DNS but not yet confirmed
	// reads pending, a different published value reads failed, no record reads
	// not_started. DMARC reads verified when a policy covers the domain — its
	// own or a parent domain's (see inherited_from) — and not_started when none
	// does. Tracking and Unsubscribe read verified once their CNAME resolves and
	// its certificate is issued, pending until then, and failed when it did not
	// activate within 72 hours.
	Status string `json:"status"`
	TTL    string `json:"ttl"`
	Type   string `json:"type"`
	Value  string `json:"value"`
}

